    DimBackground = true,
    WindowScale = 1.05,
    FontFamily = "rbxasset://fonts/families/Roboto.json",
    GlassTransparency = 0.18,
    WorldBlur = true,
    BlurSize = 3,
    OnChanged = function(key, value, state)
