if tPart then
Core.CurrentTargetPart = tPart
Core.CurrentTargetRawPosition = tPart.Position
Core.CurrentTargetPosition = Core.predictPosition(tPart)
Core.CurrentTargetCharacter = Core.LockedTargetPlayer.Character
