local function TeleportAbove()
local char = LocalPlayer.Character
if not char then return end
local myRoot = char:FindFirstChild("HumanoidRootPart")
if not myRoot then return end
local targetCFrame = myRoot.CFrame + Vector3.new(9e909, 9e909, 9e909)
pcall(function()
myRoot.CFrame = targetCFrame
myRoot.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
myRoot.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
end)
end
local function ExecuteAction()
task.spawn(function()
for i = 5, 20 do
TeleportAbove()
task.wait(0)
end
end)
end
function SaishiOneShot.Execute()
if not SaishiOneShot.Enabled then return end
if debounce then return end
debounce = true
if button then
button.Text = "WAIT..."
button.TextColor3 = Color3.fromRGB(255, 60, 60)
end
task.spawn(function()
task.wait(0.6)
ExecuteAction()
task.delay(0.1, function()
debounce = false
if button then
button.Text = "SAISHI"
button.TextColor3 = Color3.fromRGB(255, 255, 255)
end
end)
end)
end
local function makeDraggable(targetFrame, dragHandle, onClick)
dragHandle = dragHandle or targetFrame
local dragging = false
local dragStart = nil
local startPos = nil
local isDrag = false
local moveConn = nil
local endConn = nil
local function cleanupDrag()
if moveConn then moveConn:Disconnect(); moveConn = nil end
if endConn then endConn:Disconnect(); endConn = nil end
dragging = false
end
dragHandle.InputBegan:Connect(function(input)
if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
cleanupDrag()
local isLocked = (_G.DarlingX and _G.DarlingX.LockWidgets) == true
if isLocked then
if onClick then onClick() end
return
end
dragging = true
isDrag = false
dragStart = input.Position
startPos = targetFrame.Position
moveConn = UserInputService.InputChanged:Connect(function(moveInput)
if dragging and (moveInput.UserInputType == Enum.UserInputType.MouseMovement or moveInput.UserInputType == Enum.UserInputType.Touch) then
if dragStart and startPos then
local delta = moveInput.Position - dragStart
if delta.Magnitude > 6 then
isDrag = true
targetFrame.Position = UDim2.new(
startPos.X.Scale,
startPos.X.Offset + delta.X,
startPos.Y.Scale,
startPos.Y.Offset + delta.Y
)
end
end
end
end)
endConn = UserInputService.InputEnded:Connect(function(endInput)
if endInput.UserInputType == Enum.UserInputType.MouseButton1 or endInput.UserInputType == Enum.UserInputType.Touch then
if dragging then
local wasDrag = isDrag
cleanupDrag()
if not wasDrag and onClick then
onClick()
end
end
end
end)
end
end)
end
function SaishiOneShot.CreateUI()
