frame.Size = UDim2.new(0, 56, 0, 56)
frame.Position = UDim2.new(0.85, -56, 0.65, 0)
frame.BackgroundColor3 = Color3.fromRGB(20, 20, 26)
frame.BackgroundTransparency = 0.2
