end
end
if _G.DarlingSilentAimTarget and _G.DarlingSilentAimTarget.Parent then
local parentChar = _G.DarlingSilentAimTarget.Parent
if isAlive(parentChar) then
return _G.DarlingSilentAimTarget
end
end
