local g=e.Geometry or{Bones={}};e.Geometry=g
g.X,g.Y,g.W,g.H=x,y,w,height;g.Name=p.DisplayName;g.Health,g.MaxHealth=h.Health,h.MaxHealth;g.Distance=distance;g.Equipment=e.Equipment
