pcall(sff, "FIntRenderShadowIntensity", "0")
pcall(sff, "FFlagGlobalWindRendering", "False")
pcall(sff, "FIntFRMMinGrassDistance", "0")
pcall(sff, "FIntFRMMaxGrassDistance", "0")
