if _G.DarlingBlacklistedPlayers[player.UserId] or _G.DarlingBlacklistedPlayers[player.Name] then
return true
end
end
if _G.PlayerBlacklist then
if _G.PlayerBlacklist[player.UserId] or _G.PlayerBlacklist[player.Name] then
return true
end
end
