floatBtn.TextColor3 = Color3.fromRGB(180, 180, 180)
end
end
local function startTrackingLoop()
if trackerConn then trackerConn:Disconnect(); trackerConn = nil end
trackerConn = RunService.Stepped:Connect(function()
