p.RightKnee=angles(22*reach+18*coil-13*cut,0,0)
p.LeftKnee=angles(18*reach+13*coil-10*cut,0,0)
elseif mode=="arrival" then
local walk=phase(t,39.7,40.05)*(1-phase(t,41.7,42.15))
