local d, _ = GeoBuilder.createDiamond(crownFolder, Vector3.new(0.6, 1.3, 0.6), crownCirclet.CFrame, Color3.fromRGB(0, 240, 255), Enum.Material.Neon, 0)
table.insert(crownDiamonds, {part = d, theta = theta})
end
local familiars = {}
for i = 1, 8 do
