makeKeyframeNumberSeq({{0, 0}, {0.8, 0.1}, {1, 1}}),
NumberRange.new(0.8, 1.4)
)
table.insert(familiars, {part = fPart, index = i, orbitRadius = 11.0, baseSpeed = 1.9})
end
