local bank=math.sin(t*.55)*1.5*(1-phase(t,5,8))
camera.CFrame=CFrame.lookAt(ORIGIN+pos+sway,ORIGIN+focus)*angle(0,0,bank)
camera.Focus=C(ORIGIN+focus); camera.FieldOfView=fov
