function BuddhaRainbow.toggle(state)
if state ~= nil then
if state then BuddhaRainbow.start() else BuddhaRainbow.stop() end
else
if BuddhaRainbow.Enabled then BuddhaRainbow.stop() else BuddhaRainbow.start() end
end
