local function EnsureConfigFolder()
if typeof(isfolder) == "function" and typeof(makefolder) == "function" then
if not isfolder(ConfigFolder) then
makefolder(ConfigFolder)
end
return true
end
return false
end
local function DeepCopy(value)
if type(value) ~= "table" then
return value
end
local copy = {}
for k, v in pairs(value) do
copy[k] = DeepCopy(v)
end
return copy
end
local function SaveConfig()
if not EnsureConfigFolder() then
return
end
if typeof(writefile) ~= "function" then
return
end
local data = {}
for _, key in ipairs(ConfigKeys) do
if _G[key] ~= nil then
data[key] = DeepCopy(_G[key])
end
end
local ok, encoded = pcall(function()
return HttpService:JSONEncode(data)
end)
if ok then
pcall(function()
writefile(ConfigFile, encoded)
end)
end
end
local function ReadConfigFile(path)
if typeof(isfile) ~= "function" or typeof(readfile) ~= "function" then
return false
end
if not isfile(path) then
return false
end
local ok, raw = pcall(readfile, path)
if not (ok and type(raw) == "string" and raw ~= "") then
return false
end
local okDecode, data = pcall(function()
return HttpService:JSONDecode(raw)
end)
if not (okDecode and type(data) == "table") then
return false
end
for _, key in ipairs(ConfigKeys) do
if data[key] ~= nil then
_G[key] = data[key]
end
end
return true
end
local function LoadConfig()
if ReadConfigFile(ConfigFile) then
return
end
if not ReadConfigFile(ConfigLegacyFile) then
return
end
SaveConfig()
pcall(function()
if typeof(isfile) == "function" and typeof(delfile) == "function"
and isfile(ConfigFile) and isfile(ConfigLegacyFile) then
delfile(ConfigLegacyFile)
end
end)
end
