if now >= nextAbortAt then
nextAbortAt = now + 0.1
local ok, stop = pcall(abortCheck)
if ok and stop then
aborted = true
if tween then
tween:Cancel()
end
end
end
end
end)
pcall(function()
if liveTarget then
local timeout = tick()
