if cf.Position.Y < 0 then
ClearHover()
return
end
goal = cf
end
end
if not goal then
goal = HoldCFrame
if goal and goal.Position.Y < 0 then
ClearHover()
return
end
end
if not goal then
return
end
if not LiveHoldFn then
HoldCFrame = goal
end
