if char then
for _, p in ipairs(char:GetDescendants()) do
if p:IsA("BasePart") then
p.CanCollide = false
end
end
end
local dist = (goal.Position - hrp.Position).Magnitude
if dist <= 3 then
hrp.CFrame = goal
else
local step = math.min(dist, HoverSpeedNow() * (dt or (1 / 60)))
hrp.CFrame = hrp.CFrame:Lerp(goal, step / dist)
end
end)
