if p1 and p1:IsA("BasePart") then
local owner = p1:FindFirstAncestorWhichIsA("Model")
local otherHum = owner and owner:FindFirstChildOfClass("Humanoid")
if otherHum and otherHum ~= hum then
return true
end
end
end
return false
end
