return AttackSeedCache
end
if AttackSeedRemote then
local ok, seed = pcall(function()
return AttackSeedRemote:InvokeServer()
end)
if ok and seed then
AttackSeedCache = seed
AttackSeedAt = now
return seed
end
end
return AttackSeedCache or 1
end
